# Adding New Entities

This guide walks through adding a completely new entity to the Boomerang CRM.

## Checklist

When adding a new entity, you need to create/update files in the following order:

1. Database migration
2. Database model
3. Zod validators
4. Service layer
5. Controller
6. Routes
7. Admin UI components
8. Tests
9. API documentation

## Step-by-Step Example

We will use a hypothetical "Sponsors" entity as an example.

### 1. Database Migration

```bash
npx knex migrate:make create_sponsors_table
```

```typescript
// src/db/migrations/20260215_create_sponsors_table.ts
import { Knex } from 'knex';

export async function up(knex: Knex): Promise<void> {
  await knex.schema.createTable('sponsors', (table) => {
    table.uuid('id').primary().defaultTo(knex.fn.uuid());
    table.varchar('name', 255).notNullable();
    table.varchar('contact_name', 255);
    table.varchar('contact_email', 255);
    table.varchar('contact_phone', 20);
    table.text('notes');
    table.boolean('is_active').defaultTo(true);
    table.timestamps(true, true); // created_at, updated_at
  });

  // Add indexes
  await knex.schema.raw(
    'CREATE INDEX idx_sponsors_name ON sponsors(name)'
  );
}

export async function down(knex: Knex): Promise<void> {
  await knex.schema.dropTableIfExists('sponsors');
}
```

Run the migration:
```bash
npm run db:migrate
```

### 2. Database Model

```typescript
// src/db/models/sponsor-model.ts
import { db } from '../connection';

export interface Sponsor {
  id: string;
  name: string;
  contact_name: string | null;
  contact_email: string | null;
  contact_phone: string | null;
  notes: string | null;
  is_active: boolean;
  created_at: Date;
  updated_at: Date;
}

export async function findAll(filters: {
  search?: string;
  is_active?: boolean;
  page?: number;
  per_page?: number;
}) {
  const { search, is_active, page = 1, per_page = 25 } = filters;
  const query = db('sponsors').select('*');

  if (search) {
    query.whereILike('name', `%${search}%`);
  }
  if (is_active !== undefined) {
    query.where('is_active', is_active);
  }

  const total = await query.clone().count('id as count').first();
  const data = await query
    .orderBy('created_at', 'desc')
    .offset((page - 1) * per_page)
    .limit(per_page);

  return { data, total: Number(total?.count ?? 0), page, per_page };
}

export async function findById(id: string) {
  return db('sponsors').where('id', id).first();
}

export async function create(input: Omit<Sponsor, 'id' | 'created_at' | 'updated_at'>) {
  const [sponsor] = await db('sponsors').insert(input).returning('*');
  return sponsor;
}

export async function update(id: string, input: Partial<Sponsor>) {
  const [sponsor] = await db('sponsors')
    .where('id', id)
    .update({ ...input, updated_at: new Date() })
    .returning('*');
  return sponsor;
}

export async function remove(id: string) {
  return db('sponsors').where('id', id).update({ is_active: false });
}
```

### 3. Zod Validators

```typescript
// src/api/validators/sponsor-validator.ts
import { z } from 'zod';

export const CreateSponsorSchema = z.object({
  name: z.string().min(1).max(255),
  contact_name: z.string().max(255).optional(),
  contact_email: z.string().email().optional(),
  contact_phone: z.string().max(20).optional(),
  notes: z.string().optional(),
});

export const UpdateSponsorSchema = CreateSponsorSchema.partial();

export const ListSponsorsQuerySchema = z.object({
  search: z.string().optional(),
  is_active: z.coerce.boolean().optional(),
  page: z.coerce.number().int().positive().default(1),
  per_page: z.coerce.number().int().positive().max(100).default(25),
});

export type CreateSponsorInput = z.infer<typeof CreateSponsorSchema>;
export type UpdateSponsorInput = z.infer<typeof UpdateSponsorSchema>;
```

### 4. Service Layer

```typescript
// src/api/services/sponsor-service.ts
import * as SponsorModel from '../../db/models/sponsor-model';
import { CreateSponsorInput, UpdateSponsorInput } from '../validators/sponsor-validator';
import { AppError } from '../middleware/error-handler';

export async function listSponsors(filters: Parameters<typeof SponsorModel.findAll>[0]) {
  return SponsorModel.findAll(filters);
}

export async function getSponsor(id: string) {
  const sponsor = await SponsorModel.findById(id);
  if (!sponsor) throw new AppError(404, 'NOT_FOUND', 'Sponsor not found');
  return sponsor;
}

export async function createSponsor(input: CreateSponsorInput) {
  return SponsorModel.create({ ...input, is_active: true });
}

export async function updateSponsor(id: string, input: UpdateSponsorInput) {
  await getSponsor(id); // Throws if not found
  return SponsorModel.update(id, input);
}

export async function deleteSponsor(id: string) {
  await getSponsor(id);
  return SponsorModel.remove(id);
}
```

### 5. Controller

```typescript
// src/api/controllers/sponsor-controller.ts
import { Request, Response, NextFunction } from 'express';
import * as SponsorService from '../services/sponsor-service';
import { CreateSponsorSchema, UpdateSponsorSchema, ListSponsorsQuerySchema } from '../validators/sponsor-validator';

export async function list(req: Request, res: Response, next: NextFunction) {
  try {
    const query = ListSponsorsQuerySchema.parse(req.query);
    const result = await SponsorService.listSponsors(query);
    res.json({
      success: true,
      data: result.data,
      meta: { page: result.page, per_page: result.per_page, total: result.total },
    });
  } catch (err) { next(err); }
}

export async function get(req: Request, res: Response, next: NextFunction) {
  try {
    const sponsor = await SponsorService.getSponsor(req.params.id);
    res.json({ success: true, data: sponsor });
  } catch (err) { next(err); }
}

export async function create(req: Request, res: Response, next: NextFunction) {
  try {
    const input = CreateSponsorSchema.parse(req.body);
    const sponsor = await SponsorService.createSponsor(input);
    res.status(201).json({ success: true, data: sponsor });
  } catch (err) { next(err); }
}

export async function update(req: Request, res: Response, next: NextFunction) {
  try {
    const input = UpdateSponsorSchema.parse(req.body);
    const sponsor = await SponsorService.updateSponsor(req.params.id, input);
    res.json({ success: true, data: sponsor });
  } catch (err) { next(err); }
}

export async function remove(req: Request, res: Response, next: NextFunction) {
  try {
    await SponsorService.deleteSponsor(req.params.id);
    res.json({ success: true, data: null });
  } catch (err) { next(err); }
}
```

### 6. Routes

```typescript
// src/api/routes/sponsor-routes.ts
import { Router } from 'express';
import { authenticate, authorize } from '../middleware/auth';
import * as SponsorController from '../controllers/sponsor-controller';

const router = Router();

router.get('/', authenticate, SponsorController.list);
router.get('/:id', authenticate, SponsorController.get);
router.post('/', authenticate, authorize(['admin']), SponsorController.create);
router.put('/:id', authenticate, authorize(['admin']), SponsorController.update);
router.delete('/:id', authenticate, authorize(['admin']), SponsorController.remove);

export default router;
```

Register in the main router:
```typescript
// src/api/routes/index.ts
import sponsorRoutes from './sponsor-routes';
router.use('/sponsors', sponsorRoutes);
```

### 7. Admin UI Components

Create the following in `admin-ui/src/`:

- `pages/sponsors/SponsorListPage.tsx` - Table view with filters
- `pages/sponsors/SponsorCardPage.tsx` - Detail view
- `pages/sponsors/SponsorForm.tsx` - Create/edit form
- Add route to router
- Add Hebrew translations to `i18n/he.json`

### 8. Tests

- `tests/unit/services/sponsor-service.test.ts` - Unit tests for service logic
- `tests/integration/api/sponsors.test.ts` - API endpoint tests

### 9. API Documentation

Update the OpenAPI spec (`src/api/openapi.yaml`) with the new endpoints.

## Patterns to Follow

- Use the existing entities (institutions, businesses) as reference implementations
- All entities use UUID primary keys
- All entities have `created_at` / `updated_at` timestamps
- Use soft deletes for main entities
- Always add database indexes for foreign keys and commonly queried columns
- Always add Zod validation for all input
- Write both `up()` and `down()` in migrations

# Forgot Password Implementation Plan (Task #64)

**Status:** Documented for implementation
**Priority:** P0 - Critical
**Issue:** sr-uxd UX-001 - No password recovery flow on any platform

## Overview

This document outlines the complete forgot password implementation across all platforms. This is a complex feature requiring backend tokens, email infrastructure, and frontend pages for 3 authenticated platforms.

## Backend Implementation

### 1. Database Schema Changes

Add password reset token tracking to Prisma schema:

```prisma
model PasswordResetToken {
  id            String   @id @default(uuid())
  token         String   @unique
  email         String?  // For system users (CRM/CMS)
  personalCode  String?  // For students
  expiresAt     DateTime
  used          Boolean  @default(false)
  createdAt     DateTime @default(now())

  @@index([token])
  @@index([email])
  @@index([personalCode])
}
```

### 2. DTOs

**backend/src/auth/dto/request-password-reset.dto.ts**
```typescript
import { ApiProperty } from '@nestjs/swagger';
import { IsEmail, IsOptional, IsString } from 'class-validator';

export class RequestPasswordResetDto {
  @ApiProperty({ required: false })
  @IsOptional()
  @IsEmail()
  email?: string; // For system users

  @ApiProperty({ required: false })
  @IsOptional()
  @IsString()
  personalCode?: string; // For students
}
```

**backend/src/auth/dto/confirm-password-reset.dto.ts**
```typescript
import { ApiProperty } from '@nestjs/swagger';
import { IsString, MinLength } from 'class-validator';

export class ConfirmPasswordResetDto {
  @ApiProperty()
  @IsString()
  token: string;

  @ApiProperty()
  @IsString()
  @MinLength(8)
  newPassword: string;
}
```

### 3. Auth Service Methods

**backend/src/auth/auth.service.ts** - Add methods:

```typescript
async requestPasswordReset(dto: RequestPasswordResetDto) {
  const token = randomBytes(32).toString('hex');
  const expiresAt = new Date(Date.now() + 60 * 60 * 1000); // 1 hour

  // Handle system user (CRM/CMS)
  if (dto.email) {
    const user = await this.prisma.systemUser.findUnique({
      where: { email: dto.email },
    });

    if (!user) {
      // Don't reveal if email exists (security best practice)
      return { message: 'If email exists, password reset link sent' };
    }

    await this.prisma.passwordResetToken.create({
      data: { token, email: dto.email, expiresAt },
    });

    // Send email with reset link
    const resetLink = `${process.env.FRONTEND_URL}/reset-password?token=${token}`;
    await this.notificationsService.sendEmail({
      to: dto.email,
      subject: 'בומרנג - איפוס סיסמה',
      html: `
        <div dir="rtl">
          <h2>איפוס סיסמה</h2>
          <p>קיבלנו בקשה לאיפוס הסיסמה שלך.</p>
          <p><a href="${resetLink}">לחץ כאן לאיפוס הסיסמה</a></p>
          <p>הקישור תקף למשך שעה אחת.</p>
          <p>אם לא ביקשת איפוס, אנא התעלם ממייל זה.</p>
        </div>
      `,
    });

    return { message: 'If email exists, password reset link sent' };
  }

  // Handle student (Student Portal)
  if (dto.personalCode) {
    const student = await this.prisma.student.findUnique({
      where: { personalCode: dto.personalCode },
    });

    if (!student || !student.email) {
      return { message: 'If personal code exists, password reset link sent' };
    }

    await this.prisma.passwordResetToken.create({
      data: { token, personalCode: dto.personalCode, expiresAt },
    });

    const resetLink = `${process.env.STUDENT_PORTAL_URL}/reset-password?token=${token}`;
    await this.notificationsService.sendEmail({
      to: student.email,
      subject: 'בומרנג - איפוס סיסמה',
      html: `
        <div dir="rtl">
          <h2>איפוס סיסמה</h2>
          <p>קיבלנו בקשה לאיפוס הסיסמה של הקוד האישי שלך: ${dto.personalCode}</p>
          <p><a href="${resetLink}">לחץ כאן לאיפוס הסיסמה</a></p>
          <p>הקישור תקף למשך שעה אחת.</p>
        </div>
      `,
    });

    return { message: 'If personal code exists, password reset link sent' };
  }

  throw new BadRequestException('Email or personalCode required');
}

async confirmPasswordReset(dto: ConfirmPasswordResetDto) {
  const resetToken = await this.prisma.passwordResetToken.findUnique({
    where: { token: dto.token },
  });

  if (!resetToken || resetToken.used || new Date() > resetToken.expiresAt) {
    throw new UnauthorizedException('Invalid or expired reset token');
  }

  // Hash new password
  const hashedPassword = await bcrypt.hash(dto.newPassword, 12);

  // Update password for system user or student
  if (resetToken.email) {
    await this.prisma.systemUser.update({
      where: { email: resetToken.email },
      data: { password: hashedPassword },
    });
  } else if (resetToken.personalCode) {
    await this.prisma.student.update({
      where: { personalCode: resetToken.personalCode },
      data: { password: hashedPassword },
    });
  }

  // Mark token as used
  await this.prisma.passwordResetToken.update({
    where: { token: dto.token },
    data: { used: true },
  });

  return { message: 'Password reset successful' };
}
```

### 4. Auth Controller Endpoints

**backend/src/auth/auth.controller.ts** - Add routes:

```typescript
@Post('request-password-reset')
@Throttle({ default: { ttl: 60000, limit: 3 } }) // Max 3 requests per minute
@ApiOperation({ summary: 'Request password reset link' })
requestPasswordReset(@Body() dto: RequestPasswordResetDto) {
  return this.authService.requestPasswordReset(dto);
}

@Post('confirm-password-reset')
@Throttle({ default: { ttl: 60000, limit: 5 } })
@ApiOperation({ summary: 'Confirm password reset with token' })
confirmPasswordReset(@Body() dto: ConfirmPasswordResetDto) {
  return this.authService.confirmPasswordReset(dto);
}
```

