"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import Link from "next/link";

export default function ForgotPasswordPage() {
  const [email, setEmail] = useState("");
  const [loading, setLoading] = useState(false);
  const [sent, setSent] = useState(false);
  const router = useRouter();

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);

    try {
      const res = await fetch(`${process.env.NEXT_PUBLIC_API_URL}/auth/request-password-reset`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email }),
      });

      if (!res.ok) throw new Error();
      setSent(true);
    } catch {
      // Show generic message for security
      setSent(true);
    } finally {
      setLoading(false);
    }
  };

  if (sent) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-50">
        <div className="max-w-md w-full bg-white rounded-2xl shadow-sm p-8 text-center">
          <div className="text-boomerang-600 text-5xl mb-4">✓</div>
          <h2 className="text-xl font-bold mb-2">נשלח קישור לאיפוס סיסמה</h2>
          <p className="text-gray-600 mb-6">
            אם האימייל קיים במערכת, נשלח אליו קישור לאיפוס סיסמה.
            בדוק את תיבת הדואר שלך.
          </p>
          <Link href="/login" className="btn-primary inline-block">
            חזרה להתחברות
          </Link>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen flex items-center justify-center bg-gray-50">
      <div className="max-w-md w-full bg-white rounded-2xl shadow-sm p-8">
        <h1 className="text-2xl font-bold text-center mb-2">שכחת סיסמה?</h1>
        <p className="text-gray-600 text-center mb-6">
          הזן את כתובת האימייל שלך ונשלח לך קישור לאיפוס הסיסמה
        </p>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <label className="label-field">אימייל</label>
            <input
              type="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              required
              className="input-field"
            />
          </div>

          <button type="submit" disabled={loading} className="btn-primary w-full">
            {loading ? "שולח..." : "שלח קישור לאיפוס"}
          </button>

          <Link
            href="/login"
            className="block text-center text-sm text-gray-600 hover:text-gray-900"
          >
            חזרה להתחברות
          </Link>
        </form>
      </div>
    </div>
  );
}
```

**3. Create Reset Password Page**

`crm-frontend/src/app/reset-password/page.tsx`:

```tsx
"use client";

import { useState, useEffect, Suspense } from "react";
import { useRouter, useSearchParams } from "next/navigation";
import Link from "next/link";

function ResetPasswordForm() {
  const searchParams = useSearchParams();
  const token = searchParams.get("token");
  const router = useRouter();

  const [password, setPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [success, setSuccess] = useState(false);

  if (!token) {
    return <div className="text-center text-red-600">קישור לא תקין</div>;
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError("");

    if (password !== confirmPassword) {
      setError("הסיסמאות אינן תואמות");
      return;
    }

    if (password.length < 8) {
      setError("הסיסמה חייבת להכיל לפחות 8 תווים");
      return;
    }

    setLoading(true);

    try {
      const res = await fetch(`${process.env.NEXT_PUBLIC_API_URL}/auth/confirm-password-reset`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ token, newPassword: password }),
      });

      if (!res.ok) {
        throw new Error("הקישור פג תוקף או לא תקין");
      }

      setSuccess(true);
      setTimeout(() => router.push("/login"), 2000);
    } catch (err: any) {
      setError(err.message || "שגיאה באיפוס הסיסמה");
    } finally {
      setLoading(false);
    }
  };

  if (success) {
    return (
      <div className="text-center">
        <div className="text-boomerang-600 text-5xl mb-4">✓</div>
        <h2 className="text-xl font-bold mb-2">הסיסמה אופסה בהצלחה</h2>
        <p className="text-gray-600">מעביר אותך להתחברות...</p>
      </div>
    );
  }

  return (
    <form onSubmit={handleSubmit} className="space-y-4">
      <div>
        <label className="label-field">סיסמה חדשה</label>
        <input
          type="password"
          value={password}
          onChange={(e) => setPassword(e.target.value)}
          required
          minLength={8}
          className="input-field"
        />
        <p className="text-xs text-gray-500 mt-1">לפחות 8 תווים</p>
      </div>

      <div>
        <label className="label-field">אימות סיסמה</label>
        <input
          type="password"
          value={confirmPassword}
          onChange={(e) => setConfirmPassword(e.target.value)}
          required
          className="input-field"
        />
      </div>

      {error && <div className="text-red-600 text-sm">{error}</div>}

      <button type="submit" disabled={loading} className="btn-primary w-full">
        {loading ? "מאפס סיסמה..." : "אפס סיסמה"}
      </button>

      <Link
        href="/login"
        className="block text-center text-sm text-gray-600 hover:text-gray-900"
      >
        חזרה להתחברות
      </Link>
    </form>
  );
}

export default function ResetPasswordPage() {
  return (
    <div className="min-h-screen flex items-center justify-center bg-gray-50">
      <div className="max-w-md w-full bg-white rounded-2xl shadow-sm p-8">
        <h1 className="text-2xl font-bold text-center mb-6">איפוס סיסמה</h1>
        <Suspense fallback={<div className="text-center">טוען...</div>}>
          <ResetPasswordForm />
        </Suspense>
      </div>
    </div>
  );
}
```

