### Caching activation credentials (CRM only)
```typescript
import { useStudentStore } from "@/store/studentStore";

function ActivateButton({ studentId }: { studentId: string }) {
  const setActivation = useStudentStore((s) => s.setActivation);

  const handleActivate = async () => {
    const result = await api.activateStudent(studentId);
    setActivation(studentId, {
      studentId,
      personalCode: result.personalCode,
      generatedPassword: result.generatedPassword,
      activatedAt: new Date().toISOString(),
    });
  };
}
```

