## 6. Adding New Stores

Follow this pattern when adding a new zustand store:

1. Create `src/store/newStore.ts`:
```typescript
import { create } from 'zustand';

interface NewStore {
  // State
  items: Item[];
  // Actions
  addItem: (item: Item) => void;
  removeItem: (id: string) => void;
}

export const useNewStore = create<NewStore>()((set) => ({
  items: [],
  addItem: (item) => set((state) => ({
    items: [...state.items, item],
  })),
  removeItem: (id) => set((state) => ({
    items: state.items.filter((i) => i.id !== id),
  })),
}));
```

2. If persistence is needed, wrap with `persist`:
```typescript
import { persist } from 'zustand/middleware';

export const useNewStore = create<NewStore>()(
  persist(
    (set) => ({ /* ... */ }),
    { name: 'boomerang-[app]-[store]' }
  )
);
```

3. If a hook wrapper is desired for backward compatibility, create `src/hooks/useNew.ts`.

**Do not persist sensitive data.** Passwords, tokens with long lifetimes, PII, or financial data should use in-memory stores only.

